def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    h = []
    for x in history:
        try:
            v = float(x)
            if math.isfinite(v):
                h.append(v)
        except (TypeError, ValueError):
            pass
    if not h:
        return [0.0] * horizon
    period = 24 if 'hour' in frequency.lower() else max(1, min(7, len(h)))
    cycle = h[-period:]
    return [float(max(0.0, cycle[k % len(cycle)])) for k in range(horizon)]

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    h = []
    for x in history:
        try:
            v = float(x)
            if math.isfinite(v):
                h.append(max(0.0, v))
        except (TypeError, ValueError):
            pass
    if not h:
        return [0.0] * horizon
    period = 24 if 'hour' in frequency.lower() else max(1, min(7, len(h)))
    recent = h[-period:]
    scale = 1.0
    if len(h) >= 2 * period:
        previous = h[-2 * period:-period]
        old_total = sum(previous)
        new_total = sum(recent)
        if old_total > 0.0 and new_total > 0.0:
            ratio = new_total / old_total
            scale = max(0.8, min(1.2, ratio))
    return [float(recent[k % len(recent)] * scale) for k in range(horizon)]

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    h = []
    for x in history:
        try:
            v = float(x)
            if math.isfinite(v):
                h.append(max(0.0, v))
        except (TypeError, ValueError):
            pass
    if not h:
        return [0.0] * horizon
    period = 24 if 'hour' in frequency.lower() else max(1, min(7, len(h)))
    recent = h[-period:]
    previous = h[-2 * period:-period] if len(h) >= 2 * period else recent
    template = []
    for i, latest in enumerate(recent):
        older = previous[i] if i < len(previous) else latest
        if latest == 0.0:
            template.append(0.0)
        else:
            template.append(0.75 * latest + 0.25 * older)
    return [float(template[k % len(template)]) for k in range(horizon)]
